//! Integration tests for the perception crate public API (SPEC.md §3, §3.1,
//! §3.2, §8, §13): world parsing/validation codes, presets, rotated-box AABB
//! math, gaze raycast, frustum culling, perception frames, and the glTF
//! fixture generated by `tests/tools/gen_cube_gltf.py`.

use std::path::Path;

use lookwright_core::{CameraParams, CameraPose, Projector, Quat, Vec3};
use lookwright_perception::{cast_gaze, Frustum, PerceptionFrame, World};
use serde_json::Value;

fn approx(actual: f32, expected: f32, tol: f32) {
    assert!(
        (actual - expected).abs() <= tol,
        "approx failed: {actual} vs {expected} (tol {tol})"
    );
}

fn v_approx(actual: Vec3, expected: Vec3, tol: f32) {
    approx(actual.x, expected.x, tol);
    approx(actual.y, expected.y, tol);
    approx(actual.z, expected.z, tol);
}

const CUSTOM_WORLD: &str = r#"{
  "version": 1,
  "name": "Custom World",
  "objects": [
    { "id": "rotated-box", "label": "Rotated shelf",
      "geometry": { "box": { "center_m": [0.0, 0.0, 0.0], "size_m": [2.0, 1.0, 1.0],
                             "rotation_euler_ypr_deg": [90.0, 0.0, 0.0] } } },
    { "id": "scan-cloud", "label": "Lidar scan",
      "geometry": { "points_m": [[0.0, 0.0, -2.0], [1.0, 1.0, -2.0]] } }
  ]
}"#;

// -------------------------------------------------------------------------
// World parsing (SPEC.md §3, §7)

#[test]
fn parses_custom_world_with_rotated_box_and_points() {
    let world = World::parse(CUSTOM_WORLD).unwrap();
    assert_eq!(world.name(), "Custom World");
    assert_eq!(world.objects().len(), 2);

    let shelf = &world.objects()[0];
    assert_eq!(shelf.id(), "rotated-box");
    assert_eq!(shelf.label(), "Rotated shelf");
    assert_eq!(shelf.triangles_m().len(), 12);

    let cloud = &world.objects()[1];
    assert_eq!(cloud.id(), "scan-cloud");
    let (min_m, max_m) = cloud.aabb();
    v_approx(min_m, Vec3::new(0.0, 0.0, -2.0), 1e-6);
    v_approx(max_m, Vec3::new(1.0, 1.0, -2.0), 1e-6);
}

#[test]
fn validation_codes_and_paths_match_the_spec() {
    let cases: &[(&str, &str, &str)] = &[
        // duplicate id -> W-01
        (
            r#"{ "objects": [ { "id": "sofa", "geometry": { "box": {
                 "center_m": [0,0,0], "size_m": [1,1,1] } } },
                 { "id": "sofa", "geometry": { "box": {
                 "center_m": [0,0,0], "size_m": [1,1,1] } } } ] }"#,
            "W-01",
            "/objects/1/id",
        ),
        // invalid id characters -> W-01
        (
            r#"{ "objects": [ { "id": "Big Sofa!", "geometry": { "box": {
                 "center_m": [0,0,0], "size_m": [1,1,1] } } } ] }"#,
            "W-01",
            "/objects/0/id",
        ),
        // missing geometry -> W-02
        (
            r#"{ "objects": [ { "id": "sofa" } ] }"#,
            "W-02",
            "/objects/0/geometry",
        ),
        // zero size component -> W-03
        (
            r#"{ "objects": [ { "id": "sofa", "geometry": { "box": {
                 "center_m": [0,0,0], "size_m": [2.2, 0.0, 0.9] } } } ] }"#,
            "W-03",
            "/objects/0/geometry/box/size_m",
        ),
        // empty points_m -> W-05
        (
            r#"{ "objects": [ { "id": "sofa", "geometry": { "points_m": [] } } ] }"#,
            "W-05",
            "/objects/0/geometry/points_m",
        ),
        // malformed center_m -> W-02
        (
            r#"{ "objects": [ { "id": "sofa", "geometry": { "box": {
                 "center_m": [0,0], "size_m": [1,1,1] } } } ] }"#,
            "W-02",
            "/objects/0/geometry/box/center_m",
        ),
        // malformed JSON -> P-01 at the document root
        ("{ not json", "P-01", "/"),
    ];
    for (doc, code, path) in cases {
        let issue = World::parse(doc).unwrap_err();
        assert_eq!(issue.code, *code, "code for {doc}");
        assert_eq!(issue.path, *path, "path for {doc}");
        assert!(!issue.message.is_empty());
    }
}

// -------------------------------------------------------------------------
// Presets (SPEC.md §3.1)

#[test]
fn living_room_preset_has_the_spec_objects() {
    let world = World::from_preset("living_room").unwrap();
    assert_eq!(world.name(), "Living Room");
    assert_eq!(world.objects().len(), 10);
    let ids: Vec<&str> = world.objects().iter().map(|o| o.id()).collect();
    assert!(ids.contains(&"tv"));
    assert!(ids.contains(&"painting"));
    assert!(ids.contains(&"sofa"));
}

#[test]
fn unknown_preset_is_w07() {
    let issue = World::from_preset("nope").unwrap_err();
    assert_eq!(issue.code, "W-07");
    assert_eq!(issue.path, "nope");
}

#[test]
fn preset_ids_list_all_four_and_every_preset_parses() {
    let ids = World::preset_ids();
    assert_eq!(ids, &["living_room", "office", "urban_street", "warehouse"]);
    for id in ids {
        let world = World::from_preset(id).unwrap();
        assert!(!world.objects().is_empty(), "{id} has no objects");
        for object in world.objects() {
            assert!(!object.id().is_empty());
            let (min_m, max_m) = object.aabb();
            assert!(min_m.x <= max_m.x && min_m.y <= max_m.y && min_m.z <= max_m.z);
        }
    }
}

// -------------------------------------------------------------------------
// Rotated-box AABB math (SPEC.md §3)

#[test]
fn yaw90_cube_keeps_a_unit_aabb() {
    let world = World::parse(
        r#"{ "objects": [ { "id": "cube", "geometry": { "box": {
             "center_m": [0.0, 0.0, 0.0], "size_m": [1.0, 1.0, 1.0],
             "rotation_euler_ypr_deg": [90.0, 0.0, 0.0] } } } ] }"#,
    )
    .unwrap();
    let (min_m, max_m) = world.objects()[0].aabb();
    v_approx(min_m, Vec3::new(-0.5, -0.5, -0.5), 1e-5);
    v_approx(max_m, Vec3::new(0.5, 0.5, 0.5), 1e-5);
}

#[test]
fn yaw90_swaps_x_and_z_extents() {
    // A 2 x 1 x 1 box yawed 90 deg carries its 2 m extent along world z and
    // its 1 m extent along world x (AABB of the 8 rotated corners).
    let world = World::parse(
        r#"{ "objects": [ { "id": "plank", "geometry": { "box": {
             "center_m": [1.0, 0.0, 0.0], "size_m": [2.0, 1.0, 1.0],
             "rotation_euler_ypr_deg": [90.0, 0.0, 0.0] } } } ] }"#,
    )
    .unwrap();
    let (min_m, max_m) = world.objects()[0].aabb();
    v_approx(min_m, Vec3::new(0.5, -0.5, -1.0), 1e-5);
    v_approx(max_m, Vec3::new(1.5, 0.5, 1.0), 1e-5);
}

// -------------------------------------------------------------------------
// Gaze raycast (SPEC.md §3.2) — the two CLI load-bearing examples

#[test]
fn gaze_from_the_sofa_hits_the_tv() {
    let world = World::from_preset("living_room").unwrap();
    let camera = CameraPose::new(Vec3::new(0.0, 1.7, 0.0), Quat::IDENTITY);
    let hit = cast_gaze(&world, camera.position_m, camera.forward()).unwrap();
    assert_eq!(hit.object_id, "tv");
    approx(hit.distance_m, 4.86, 1e-4);
    v_approx(hit.point_m, Vec3::new(0.0, 1.7, -4.86), 1e-4);
}

#[test]
fn gaze_yawed_85_deg_from_midroom_hits_the_painting() {
    let world = World::from_preset("living_room").unwrap();
    let rotation = Quat::from_axis_angle_deg(Vec3::new(0.0, 1.0, 0.0), 85.0);
    let camera = CameraPose::new(Vec3::new(0.0, 1.7, -1.5), rotation);
    let hit = cast_gaze(&world, camera.position_m, camera.forward()).unwrap();
    assert_eq!(hit.object_id, "painting");
}

// -------------------------------------------------------------------------
// Frustum culling (SPEC.md §8)

fn identity_frustum() -> Frustum {
    let camera = CameraPose::new(Vec3::ZERO, Quat::IDENTITY);
    let params = CameraParams::new(90.0, 0.05, 50.0, 1.0);
    let projector = Projector::new(&camera, &params, [64, 64]);
    Frustum::from_vp(projector.vp_matrix())
}

fn box_at(center_m: Vec3, size_m: Vec3) -> (Vec3, Vec3) {
    let half = Vec3::new(size_m.x * 0.5, size_m.y * 0.5, size_m.z * 0.5);
    (center_m - half, center_m + half)
}

#[test]
fn frustum_cases_from_the_camera_at_origin() {
    let frustum = identity_frustum();
    let (min_m, max_m) = box_at(Vec3::new(0.0, 0.0, -5.0), Vec3::new(1.0, 1.0, 1.0));
    assert!(frustum.intersects_aabb(min_m, max_m));
    let (min_m, max_m) = box_at(Vec3::new(0.0, 0.0, 5.0), Vec3::new(1.0, 1.0, 1.0));
    assert!(!frustum.intersects_aabb(min_m, max_m));
    let (min_m, max_m) = box_at(Vec3::new(10.0, 0.0, -5.0), Vec3::new(1.0, 1.0, 1.0));
    assert!(!frustum.intersects_aabb(min_m, max_m));
    let (min_m, max_m) = box_at(Vec3::new(-5.0, 0.0, -5.0), Vec3::new(1.0, 1.0, 1.0));
    assert!(frustum.intersects_aabb(min_m, max_m));
    let (min_m, max_m) = box_at(Vec3::ZERO, Vec3::new(100.0, 100.0, 100.0));
    assert!(frustum.intersects_aabb(min_m, max_m));
}

// -------------------------------------------------------------------------
// Perception frames (SPEC.md §8)

fn living_room_frame() -> PerceptionFrame {
    let world = World::from_preset("living_room").unwrap();
    let camera = CameraPose::new(Vec3::new(0.0, 1.7, 0.0), Quat::IDENTITY);
    let params = CameraParams::new(70.0, 0.05, 50.0, 1.6);
    let projector = Projector::new(&camera, &params, [640, 400]);
    PerceptionFrame::capture(2.5, &camera, &world, &projector)
}

#[test]
fn frame_json_matches_the_spec_schema() {
    let frame = living_room_frame();
    let json = frame.to_json();
    let v: Value = serde_json::from_str(&json).unwrap();
    assert_eq!(v["schema"], "lookwright/perception-frame@1");
    assert_eq!(v["t_sec"], serde_json::json!(2.5));
    assert_eq!(
        v["camera"]["position_m"],
        serde_json::json!([0.0, 1.7, 0.0])
    );
    assert_eq!(v["camera"]["gaze_target"], "tv");
    assert!(!v["visible_objects"].as_array().unwrap().is_empty());
}

#[test]
fn frame_visible_objects_are_sorted_by_distance_then_id() {
    let v: Value = serde_json::from_str(&living_room_frame().to_json()).unwrap();
    let entries = v["visible_objects"].as_array().unwrap();
    assert!(entries.len() >= 3, "expected several visible objects");
    for pair in entries.windows(2) {
        let d0 = pair[0]["distance_m"].as_f64().unwrap();
        let d1 = pair[1]["distance_m"].as_f64().unwrap();
        assert!(d0 <= d1 + 1e-9);
        if (d0 - d1).abs() <= 1e-9 {
            assert!(pair[0]["id"].as_str().unwrap() < pair[1]["id"].as_str().unwrap());
        }
    }
}

#[test]
fn tv_bbox_px_lands_inside_the_viewport() {
    let v: Value = serde_json::from_str(&living_room_frame().to_json()).unwrap();
    let tv = v["visible_objects"]
        .as_array()
        .unwrap()
        .iter()
        .find(|entry| entry["id"] == "tv")
        .expect("tv must be visible");
    assert_eq!(tv["label"], "TV");
    let bbox = tv["bbox_px"]
        .as_array()
        .expect("tv bbox_px must not be null");
    let x0 = bbox[0].as_f64().unwrap();
    let y0 = bbox[1].as_f64().unwrap();
    let x1 = bbox[2].as_f64().unwrap();
    let y1 = bbox[3].as_f64().unwrap();
    assert!((0.0..=640.0).contains(&x0));
    assert!((0.0..=640.0).contains(&x1));
    assert!((0.0..=400.0).contains(&y0));
    assert!((0.0..=400.0).contains(&y1));
    assert!(x0 <= x1 && y0 <= y1);
    let world_min = tv["world_aabb_m"]["min_m"].as_array().unwrap();
    let world_max = tv["world_aabb_m"]["max_m"].as_array().unwrap();
    approx(world_min[0].as_f64().unwrap() as f32, -0.8, 1e-5);
    approx(world_max[0].as_f64().unwrap() as f32, 0.8, 1e-5);
}

#[test]
fn jsonld_frame_carries_context_and_types() {
    let jsonld = living_room_frame().to_jsonld();
    assert!(jsonld.starts_with("{\n  \"@context\""));
    assert!(jsonld.contains("\"@type\": \"PerceptionFrame\""));
    assert!(jsonld.contains("\"@type\": \"SpatialObject\""));
    let v: Value = serde_json::from_str(&jsonld).unwrap();
    assert_eq!(v["schema"], "lookwright/perception-frame@1");
    assert_eq!(v["camera"]["gaze_target"], "tv");
    let context = v["@context"].as_object().unwrap();
    for term in [
        "PerceptionFrame",
        "SpatialObject",
        "visible_objects",
        "gaze_target",
        "bbox_px",
        "distance_m",
        "t_sec",
    ] {
        assert!(context.contains_key(term), "missing context term {term}");
    }
}

#[test]
fn camera_enclosing_box_is_visible_with_null_bbox_px() {
    let world = World::parse(
        r#"{ "version": 1, "name": "Wrap", "objects": [
            { "id": "room_shell", "geometry": { "box": {
                "center_m": [0.0, 1.7, 0.0], "size_m": [40.0, 40.0, 40.0] } } },
            { "id": "tv", "label": "TV", "geometry": { "box": {
                "center_m": [0.0, 1.3, -4.9], "size_m": [1.6, 0.9, 0.08] } } }
        ] }"#,
    )
    .unwrap();
    let camera = CameraPose::new(Vec3::new(0.0, 1.7, 0.0), Quat::IDENTITY);
    let params = CameraParams::new(70.0, 0.05, 50.0, 1.6);
    let projector = Projector::new(&camera, &params, [640, 400]);
    let frame = PerceptionFrame::capture(0.0, &camera, &world, &projector);

    let v: Value = serde_json::from_str(&frame.to_json()).unwrap();
    let shell = v["visible_objects"]
        .as_array()
        .unwrap()
        .iter()
        .find(|entry| entry["id"] == "room_shell")
        .expect("the enclosing box must be frustum-visible");
    assert!(
        shell["bbox_px"].is_null(),
        "corners behind the camera fail to project"
    );
    // The gaze ray still passes through the shell (origin inside -> no hit)
    // and lands on the tv.
    assert_eq!(v["camera"]["gaze_target"], "tv");
}

// -------------------------------------------------------------------------
// glTF import (SPEC.md §3.2) — fixture from tests/tools/gen_cube_gltf.py

#[test]
fn loads_the_gltf_cube_fixture() {
    let world = World::load(Path::new("tests/fixtures/cube.gltf"))
        .expect("generated cube.gltf must import");
    let objects = world.objects();
    assert_eq!(objects.len(), 1);
    let cube = &objects[0];
    assert_eq!(cube.id(), "test-cube");
    assert_eq!(cube.label(), "Test Cube");
    let (min_m, max_m) = cube.aabb();
    v_approx(min_m, Vec3::new(-0.5, -0.5, -0.5), 1e-5);
    v_approx(max_m, Vec3::new(0.5, 0.5, 0.5), 1e-5);
    assert_eq!(cube.triangles_m().len(), 12);
    // A deterministic fallback tint is derived from the id hash.
    assert_eq!(cube.color_rgb(), lookwright_fallback_color("test-cube"));
}

fn lookwright_fallback_color(id: &str) -> [u8; 3] {
    // FNV-1a 32-bit of the id, low three bytes (documented rule in
    // crates/lookwright-perception/src/world.rs).
    let mut h: u32 = 0x811c_9dc5;
    for b in id.as_bytes() {
        h ^= *b as u32;
        h = h.wrapping_mul(0x0100_0193);
    }
    [
        (h & 0xff) as u8,
        ((h >> 8) & 0xff) as u8,
        ((h >> 16) & 0xff) as u8,
    ]
}

#[test]
fn gaze_hits_the_gltf_cube_at_four_point_five_meters() {
    let world = World::load(Path::new("tests/fixtures/cube.gltf")).unwrap();
    let hit = cast_gaze(&world, Vec3::new(0.0, 0.0, 5.0), Vec3::new(0.0, 0.0, -1.0))
        .expect("the gaze ray must hit the cube");
    assert_eq!(hit.object_id, "test-cube");
    approx(hit.distance_m, 4.5, 1e-4);
    v_approx(hit.point_m, Vec3::new(0.0, 0.0, 0.5), 1e-4);
}

#[test]
fn gltf_load_errors_are_p01_with_the_file_path() {
    let issue = World::load(Path::new("tests/fixtures/missing.gltf")).unwrap_err();
    assert_eq!(issue.code, "P-01");
    assert_eq!(issue.path, "tests/fixtures/missing.gltf");
    assert!(!issue.message.is_empty());
}
